interface User { id: number; name: string }
const cache = m.createCache({ driver: m.memoryDriver() });
export type _cacheNotAny = Expect<IsAny<typeof cache>>;
export type _getNotAny = Expect<IsAny<ReturnType<typeof cache.get>>>;
const typed = m.createCache<{ [k: `user:${number}`]: User; "config": { dark: boolean }; [k: `hits:${string}`]: number }>({ driver: m.memoryDriver() });
export type _userOut = Equal<Awaited<ReturnType<typeof typed.get<`user:${number}`>>>, User | undefined>;
declare const schema: t.CacheSchemaFrom<{ "user:*": import("@kingsleyweb/bun-common").StandardSchemaV1<unknown, User> }>;
export type _schemaKey = Equal<keyof typeof schema, `user:${string}`>;
export const _driverError: Error = new m.CacheDriverError({ driver: "memory", op: "get", cause: new Error("x") });
const simple = m.fromSimpleDriver({ get: async (_ns, _key) => undefined, set: async () => {}, delete: async () => true });
export type _simpleIsDriver = Equal<typeof simple extends t.CacheDriver ? true : false, true>;

declare const driver: t.CacheDriver;
const wrapped: t.FaultyDriver = m.faulty(driver, { failOn: ["get"] });
wrapped.setFaults({ down: true });
void m.runCacheDriverConformance("memory", () => ({ driver: wrapped }));
export type _clockNotAny = Expect<IsAny<ReturnType<typeof m.fakeClock>>>;
const clock = m.fakeClock();
clock.advance(1000);
export type _nowReturns = Equal<ReturnType<typeof clock.now>, number>;
export type _storedEntryNotAny = Expect<IsAny<t.StoredEntry>>;
